#!/usr/bin/env node
/**
 * Bundle the TypeScript CLI into build/gameforge-cli.cjs.
 *
 * Why bundle instead of running tsx: the desktop shell builds games from Electron's own Node, and
 * the pipeline is TypeScript. Bundling produces one CommonJS file the main process can spawn with
 * ELECTRON_RUN_AS_NODE, with no dependency on a system Node or tsx installation.
 *
 * esbuild stays external: it is required at runtime from node_modules, so the bundle stays small
 * and the platform-specific binary is resolved normally.
 */

'use strict';

const path = require('node:path');
const fs = require('node:fs');
const esbuild = require('esbuild');

const REPO_ROOT = path.resolve(__dirname, '..');
const OUT_FILE = path.join(REPO_ROOT, 'build', 'gameforge-cli.cjs');

async function main() {
  fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });

  const result = await esbuild.build({
    entryPoints: [path.join(REPO_ROOT, 'tools', 'cli', 'gameforge.ts')],
    outfile: OUT_FILE,
    bundle: true,
    platform: 'node',
    target: ['node20'],
    format: 'cjs',
    sourcemap: false,
    logLevel: 'warning',
    metafile: true,
    // Resolved from node_modules at run time; bundling the native binary would be far worse.
    external: ['esbuild'],
    banner: {
      js: '/* Generated by scripts/bundle-cli.js - do not edit. Run `npm run cli:bundle` to rebuild. */',
    },
  });

  const bytes = fs.statSync(OUT_FILE).size;
  const inputs = Object.keys(result.metafile.inputs).length;
  process.stdout.write(
    `bundled CLI: ${path.relative(REPO_ROOT, OUT_FILE)} (${inputs} modules, ${(bytes / 1024).toFixed(1)} KB)\n`
  );
}

main().catch((error) => {
  process.stderr.write(`Failed to bundle the CLI: ${error.stack || error.message}\n`);
  process.exit(1);
});
